      CommsLine(id: 'lowLives.h2', speaker: 'anvil', duration: 3.357, text: 'One ship left. Slow down, pick your shots.', mouth: '0055<<==========00000===<<<<<<<2200000000<<<<<===22', open: '014788777557763211000466899998742111685878898667642', vis: '--ooooeeeeee--ee-----eeooo--------------ee----ee---', emotion: 'warm'),
      CommsLine(id: 'lowLives.h3', speaker: 'wisp', duration: 3.31, text: 'Final reserve ship. Stay calm. You can do this.', mouth: '000<<<<<<<<====220000===<<<<<<555=====<<<<33===000', open: '00689998899777642110044788677765326857887765322110', vis: '-----------ee--------ee-------oooee--oo-----eee---', emotion: 'warm'),
