      CommsLine(id: 'levelClear.h1', speaker: 'sparrow', duration: 2.105, text: 'We did it! Sky\'s ours.', mouth: '55555555<<<<==00000<<<<<<<<<==00', open: '02787636888542111068987999753211', vis: 'ooooooo-----eee-------------ee--', emotion: 'triumphant'),
