      CommsLine(id: 'levelClear.h5', speaker: 'pip', duration: 2.174, text: 'That was amazing! Can we do it again?', mouth: '3333<<<<<<<<======<<<<<<<<<<<<<<<', open: '068788899888764325888688876898853', vis: '------------eeeee---------eeeee--', emotion: 'triumphant'),
