  'flawlessSector': CommsTriggerSpec(
    name: 'flawlessSector',
    priority: 6,
    cooldown: 10.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'flawlessSector.h0', speaker: 'admiral', duration: 3.625, text: 'Not a single ship lost in this sector. Textbook, all of you.', mouth: '55333333=======55555========222200000==332222<<<44<<<<<', open: '0366643235665453356633555345333211068536632178997788532', vis: 'oo----eeeeeeeeeoo---eeeeeeee--------eee----------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessSector.h1', speaker: 'kestrel', duration: 3.15, text: 'Every wing accounted for. That\'s how it\'s done.', mouth: '3333<<<<<<<==444444<<<==0000<<===<<<<222<<<<<222', open: '056788899985477874688853212688536898532788886321', vis: '-----oooo--ee-----oo--eeeee---ee----------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessSector.h2', speaker: 'sunny', duration: 2.827, text: 'Zero losses! That was out of this world.', mouth: '2222<<<<55<<<<<<<===========<<<444444433300', open: '0245889976899766532148787436888676457665321', vis: '--------oo-------eeee----ee----------------', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessSector.h3', speaker: 'march', duration: 3.985, text: 'Bastion reporting. Every ground team is still standing. Thank you!', mouth: '3333===5555553322000000<<33<<<<<55========<<<<<<000<<33<<<22', open: '055432344214666432116868856886677642479636898753216885589642', vis: '----eeeoooooo-------ee----------ooeee--eeeee---ee-------oo--', emotion: 'triumphant'),
