  'flawlessVictory': CommsTriggerSpec(
    name: 'flawlessVictory',
    priority: 9,
    cooldown: 30.0,
    ttl: 6.0,
    mood: CommsMood.happy,
    chain: 2,
    lines: [
      CommsLine(id: 'flawlessVictory.h0', speaker: 'admiral', duration: 5.006, text: 'All hands, all ships, all squads. Every one of you is coming home. Fleet intact!', mouth: '33<<<<4444444<<=======<<333<<<33344444444==3344<<<=======0000=======00005500', open: '0689987777547987685327885479975686767767753567788743476421156547853211002321', vis: '---------------eeeee---------------------ee-------eee---ee---eeeeeee----oo--', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h1', speaker: 'lindqvist', duration: 4.106, text: 'Beacon confirms. Full roster, no losses. I\'ve never seen it done.', mouth: '=========3333220000000<<====22000<<<<<444444444<<=======<<<<22', open: '03435655356554211006878964454211588896665322776887455537898642', vis: 'eeeeeeee----------------ee---------------ee------eeeeeee------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h2', speaker: 'rook', duration: 3.027, text: 'Perfect run! I\'m over the moon! All the moons!', mouth: '22222222<<<333333333<<<<<<<<<2222<<<<<<333====', open: '0353643688764323675798899987632378899876533321', vis: '-------------------ooooooo-------ooooo----ee--', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessVictory.h3', speaker: 'sunny', duration: 2.669, text: 'Flawless! Somebody get this pilot a constellation!', mouth: '55<<<<<<===000<<<<<<<<<<<2244333<<<<<2200', open: '05899998632117889874588853377467898654211', vis: 'oo------eee--------------------oooee-----', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessVictory.h4', speaker: 'pip', duration: 2.723, text: 'Everybody made it? Everybody? Best day ever!', mouth: '==333444======004444<<<<<22222===<<<<<<<<', open: '04555766778742117787898863217874789999743', vis: 'ee------eeeeee----------------eeee-------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h5', speaker: 'kessler', duration: 2.674, text: 'Ground\'s all present! Drinks are on Bulwark tonight!', mouth: '000444<<<<<<====0000444<<<555<<<44<<===00', open: '00677788768977421113777899677985778853211', vis: '-----------eeeeee--------oooo-------eee--', emotion: 'triumphant'),
    ],
