  'flawlessRun': CommsTriggerSpec(
    name: 'flawlessRun',
    priority: 10,
    cooldown: 60.0,
    ttl: 8.0,
    mood: CommsMood.happy,
    chain: 3,
    lines: [
      CommsLine(id: 'flawlessRun.h0', speaker: 'admiral', duration: 6.097, text: 'Five tours. Not one ship, not one squad lost. The whole fleet salutes you, pilot.', mouth: '33<<<<<===5544==000055<<<55<<==44440000055<<<<<<<<55<<<==0000444<<<<<<<<<44<<====2222<<<<<<<', open: '06899764246776432110378854788666742116875488753789668975321106678855885357788557642378896432', vis: '-------eeeoo--eee---oo---oo--ee---ee----oo--------oo---eee------ooo----------eeee-----------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h1', speaker: 'nomad', duration: 3.79, text: 'Thirty years flying, and this is the run I\'ll tell stories about.', mouth: '33344<<<<==<<<<<====<<<<<<=====44<<<<<<<<<<<===<<<<<<<222', open: '068778999748888642378856887642377889988868976478888886421', vis: '---------eee----ee--ooo---eeee--------------eeoo---------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h2', speaker: 'kestrel', duration: 3.816, text: 'Every wing, every crew, every squad. Fleet intact. Legendary.', mouth: '3334455<<<<444444444<<<33<<<<<<0000444555======<<<<<<<<222', open: '0566777887577853578788755899853216877877874323788999986421', vis: '-----oo-----------------------ee-----oooeeeeee------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h3', speaker: 'sparrow', duration: 3.296, text: 'Not a scratch on the whole fleet! You\'re unbelievable!', mouth: '55444==00044======5555555===0000000<<<<<<<<<<<<<22', open: '05776432137743467557533675421110486899988998988532', vis: 'oo---eeeee--eeee--oooo---eeee---------------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h4', speaker: 'mensah', duration: 3.287, text: 'Granite to air wing. Every trooper down here is cheering for you.', mouth: '55<<<====445553355000<<==4433<<<<<<====<<555555500', open: '05899756677766665321788657665888888534798557865321', vis: 'oooeeeeee--oo---ooo----ee----------eee---ooo------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h5', speaker: 'voss', duration: 3.45, text: 'Lantern here. All lights on, all teams home. Thank you, pilot!', mouth: '55<<<<<<<<<<<<<<<<<<<<<<<<22224444444555555555544422', open: '0488878778765325898987888643787766777632764637877532', vis: 'oooooo---ee--ee----------------------oooooo---------', emotion: 'triumphant'),
    ],
  ),
