      CommsLine(id: 'bossArrival.h2', speaker: 'rook', duration: 2.053, text: 'Oh, that\'s huge. That is really, really huge.', mouth: '222<<44<<<<<<<44<<<444======000', open: '0468877897568977888777644542111', vis: '----------------------eeeeeee--', emotion: 'urgent'),
