    lines: [
      CommsLine(id: 'defeat.h0', speaker: 'admiral', duration: 5.425, text: 'All ships totalled, but every pilot is safe. Regroup at base. We go again.', mouth: '44<<<<<<===44444220000000<<3335544==333300000055<<<<<<<44444====00005555<<<<<<<<22', open: '0689878764577776421164797885577777655553211000278868976774765432111036778897888743', vis: '----ee--eee-------------------oo--ee---ee-----oo----oo------eeeee---ooooooo-------', emotion: 'exhausted'),
