      CommsLine(id: 'defeat.h2', speaker: 'lindqvist', duration: 4.565, text: 'Recovery has your pod. Rest up. The fleet will be ready when you are.', mouth: '5555<<<<44===========22000000===<<<2200000000==<<<<<<<<<<<<<<<<<<<<22', open: '056688877765768756876421100687678853211000005368878788998878999988743', vis: 'oooo------eeeeeee------------ee--------------ee--oo------------------', emotion: 'exhausted'),
