      CommsLine(id: 'groundForceSighted.h1', speaker: 'wisp', duration: 2.286, text: 'Demon ground troops below. Marking them now.', mouth: '33333333333333<<<<====<<<<<44444222', open: '05787578767656899853278967877776421', vis: '------------------eee--------------', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h2', speaker: 'anvil', duration: 2.359, text: 'Movement on the ground. Brood infantry.', mouth: '22222<<<<55<<<<<220000<<<<<<<=======', open: '037878887578998742111489999787776421', vis: '--ooo----oo------------------eeeee--', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h3', speaker: 'kessler', duration: 2.783, text: 'Bulwark here. Brood walkers moving on our line!', mouth: '3355<<===<<<==000444<<44444<<<<<<<<<<<====', open: '045588635886321137778976756878999988876432', vis: '--oo--eeee--ee-----oo-----------------ee--', emotion: 'urgent'),
