      CommsLine(id: 'groundForceSighted.h6', speaker: 'kessler', duration: 2.077, text: 'Enemy armor on the ridge! Big ones!', mouth: '==555<<<<<<44<<<========<<<<==00', open: '03677898998778875321466689764211', vis: 'eeoo------------eee---------ee--', emotion: 'urgent'),
