      CommsLine(id: 'allyUnderAttack.h1', speaker: 'kessler', duration: 2.368, text: 'Please shoot these enemies! They\'re all over us!', mouth: '5533=====33334444444444<<<<<<<<===00', open: '046543256656577776421479999978853211', vis: 'oo--eee------------ee----------eee--', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h2', speaker: 'voss', duration: 2.467, text: 'Pick up some homing missiles! We need them off our backs!', mouth: '333344<<<<<<<<<<<<<4444<<<<<<<<<<===00', open: '06787788878888753267777888788589853211', vis: '--------------------------------eeee--', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h3', speaker: 'march', duration: 5.132, text: 'Bastion to air wing, my teams are taking fire. Requesting support!', mouth: '33<<<<====<<======4444<<552222<<3344555555544444<<<<<22222222244======<<<<===', open: '05898632378856656567778975322688557776776686764798886421664785666685678985321', vis: '------ee---eeee------ooooo----------oo--------------------------eeeeeoooooeee', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h4', speaker: 'mensah', duration: 2.629, text: 'Granite\'s surrounded! Anything you\'ve got, send it down!', mouth: '0033322222445555====444<<<=======<<<<222', open: '0146643546765321355677689743277858986421', vis: '------------oo--eee---oo--eeeeeeeee-----', emotion: 'panicked'),
