      CommsLine(id: 'allyUnderAttack.h6', speaker: 'march', duration: 3.54, text: 'Bastion is under heavy fire! We need you now!', mouth: '33443333333333344422<<<<<<<0055<<<<<<<<<<<55<<<<<<2200', open: '057765665666536666448888753213798888789853378998753211', vis: '-----------------------------oo-----------ooeeee------', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h7', speaker: 'mensah', duration: 1.56, text: 'Granite\'s taking a beating! Help!', mouth: '2222222444444=========22', open: '037874277774677753278742', vis: '-------------eeeeee-----', emotion: 'panicked'),
