      CommsLine(id: 'allySaved.h2', speaker: 'march', duration: 2.477, text: 'Pressure\'s off. Bastion thanks you, air wing.', mouth: '000==<<<<==00000<<<<<<<<4444<<<<<<<<22', open: '00677888642110178888889877768888888632', vis: '---ee----ee------eeee------------ooo--', emotion: 'warm'),
