      CommsLine(id: 'allySaved.h7', speaker: 'kessler', duration: 2.866, text: 'Whew. That was close. Thanks, friend!', mouth: '000000<<<2200000055====<<<<===00000===<<<55', open: '0000058864211006866544588754321178764799874', vis: '-----------------ooee------eee-----ee---ooo', emotion: 'exhausted'),
