      CommsLine(id: 'broodTaunt.h1', speaker: 'rook', duration: 2.277, text: 'Big words. Tiny firing window.', mouth: '3355444222000===<<<<<<<<44333322200', open: '05667764321102278997898876654443211', vis: '--oo---------ee--------------------', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h2', speaker: 'sparrow', duration: 2.198, text: 'Your move, then. Try to impress me.', mouth: '222<<<<<<<<====000004444433222200', open: '047999987465432110057666455343211', vis: '----ooo----eeee------------------', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h3', speaker: 'anvil', duration: 3.192, text: 'Nice speech. Shame about your aim.', mouth: '5555<<<<====333===0000<<<<<<<555<<<<<<44<<<<2200', open: '047788877675653432110488999987758985787788754211', vis: 'ooo----eeeee---ee----eee-----ooo----oo--eee-----', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h4', speaker: 'kestrel', duration: 3.087, text: 'Challenge received. Hold your formation.', mouth: '=====<<<<<<<===443322000000<<<44<<33<<<<<<33333', open: '02337889987776567653211000689977885688875455532', vis: 'eeee--------eee-----------oooo-----------------', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h5', speaker: 'sunny', duration: 2.939, text: 'Two stars for that threat. Needs more sunshine.', mouth: '55<<<<<<<000000<<333444444222<<<<<<<<<<<<<<22', open: '068887643216867886667646864258889888889998642', vis: 'ooooo---eee------------------------------oo--', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h6', speaker: 'pip', duration: 1.99, text: 'I can be scary too! Probably!', mouth: '4444<<<<<<<<<44555000<<<<<<<<<', open: '068788877888677753216888799743', vis: '--eeeeee---ee--oooooo---------', emotion: 'excited'),
      CommsLine(id: 'broodTaunt.h7', speaker: 'nomad', duration: 3.483, text: 'Easy, friend. Save some thunder for the next round.', mouth: '44<<<<<<4444440000000<<==<<<<<<<<<44<<<==<<<<<===0000', open: '06898985777753211004788778857899857799766899886421110', vis: '-----------------------eeoooooo--------ee-----eeee---', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h8', speaker: 'wisp', duration: 3.489, text: 'Translation received. Tactical value: questionable.', mouth: '==<<<<<<<<<<444==000000000000===55<<<<<55222<<5555555', open: '04887899888676533211000000037765768988874227887666532', vis: 'ee--------ee---eee-----------eeeoo----ooo-----oooo---', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h9', speaker: 'lindqvist', duration: 3.348, text: 'Noted. Logged. Still ignoring it.', mouth: '55<<<=====000000000<<<22==0000000000==<<<<<<4442222', open: '058887654211100000588743321100000002379878887763321', vis: 'oo---eeeee--------------ee---------eeeeee----------', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h10', speaker: 'march', duration: 2.844, text: 'Bastion is staying put. Bring your best move.', mouth: '333<<==<<44===<<<333220000<<<<<<<<==<<<<<00', open: '0578877887764788746532110489997897478865321', vis: '----eeeee--ee--oo----------------eee-------', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h11', speaker: 'kessler', duration: 2.004, text: 'Come closer. The ground crew has a comeback.', mouth: '222222===220033<<<<<<<33<<<<<22', open: '0453787653211558987887658898642', vis: '------ee-----------------------', emotion: 'teasing'),
    ],
  ),
  'playerRespawn': CommsTriggerSpec(
    name: 'playerRespawn',
    priority: 5,
    cooldown: 6.0,
    ttl: 4.0,
    delay: 0.6,
    lines: [
      CommsLine(id: 'playerRespawn.h0', speaker: 'admiral', duration: 3.801, text: 'Spare ship on deck four, launch! You\'re clear, pilot.', mouth: '00===<<=====<<<<<<<<554442222<<<<=====00555555<<334444====', open: '0232789778768988853267766321589976653211378537885677776321', vis: 'eeee---eeee--oo---eeoo------oo---eeeee--oo------------ee--', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h1', speaker: 'lindqvist', duration: 3.163, text: 'Reserve fighter is hot. Welcome back to the fight.', mouth: '5555<<<<44========22==00000<<<<<<<<2222222222000', open: '057789747755543257434211006886889954354266533211', vis: 'oooo------eeeee-----ee--------oo------------ee--', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h2', speaker: 'kestrel', duration: 3.182, text: 'New ship, same pilot. Form up on me.', mouth: '00000<<<<====222===<<<44444220000<<<<<<<<<443333', open: '000058998768642123788667765321106889957788766532', vis: '----ooooeee-----ee----------------------oo------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h3', speaker: 'nomad', duration: 3.318, text: 'Fresh paint, fresh engines. Take it easy for a second.', mouth: '=====<<<55500000<<<5555==00000<<<<<<<444===2222200', open: '02774799753217878986654432110588888887776674444211', vis: 'eeeee--ooooo--eeeooooooee---------------ee--------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h4', speaker: 'anvil', duration: 2.018, text: 'Back in the air. Shake it off.', mouth: '5555==444<<<<<000==<<<<<5550000', open: '0368766778974321126898997532110', vis: 'oo--ee-----------eee---oooee---', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h5', speaker: 'sparrow', duration: 2.295, text: 'There you are! Don\'t scare me like that.', mouth: '0000<<<554444=========<<<<<<44=====', open: '00058877777764215874378998747754321', vis: '-------oo----eeeeeeee--oo-----eee--', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h6', speaker: 'rook', duration: 2.045, text: 'New ship smell! Try not to scratch this one.', mouth: '55<<===333<<<222<<44<<<<<333222', open: '0489778557886437887689857655421', vis: 'ooooee-------------------------', emotion: 'teasing'),
      CommsLine(id: 'playerRespawn.h7', speaker: 'wisp', duration: 3.463, text: 'Reserve ship launched. Shields at full. Blink and go.', mouth: '333<<<<<<<33<<<<====000==<<<<<<====55222224444444422', open: '0568997788568876554211057899789536776324787777877532', vis: '------ee----oo--eeeee--eeeooo--ee--oo---------------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h8', speaker: 'sunny', duration: 2.232, text: 'Rise and shine! Look who\'s back.', mouth: '000<<<<<==<<<<<<2200000<<<<<<===00', open: '0058988866888875321168688568864211', vis: '--------ee-------------------eee--', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h9', speaker: 'pip', duration: 2.046, text: 'You\'re back! I knew you\'d be back!', mouth: '33<<55<<===000<<<<<<<<<<<<<2200', open: '0589748864211688998887878874211', vis: '----oo--eee----ooo-------------', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h10', speaker: 'march', duration: 2.574, text: 'Bastion sees your new ship. We\'re still with you.', mouth: '33<<<<<<<<<<444<<<==442222==<<<<<444222', open: '068886898678777888767742687789995775421', vis: '----eeeeee--------ee------eeee---------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h11', speaker: 'kessler', duration: 2.2, text: 'Ground\'s glad to see you up there again!', mouth: '2222<<<<<<<<<===<<<<<<<<=======00', open: '036788747897765678985898756654211', vis: '-----------ooee---------eeeeee---', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h12', speaker: 'voss', duration: 2.56, text: 'Lantern lights for the new ship. Go get them.', mouth: '55<<<<<<<<==444<<==<<550000000000444222', open: '058987888874777887788532110168786776421', vis: 'ooee------ee-----eeeooo----------------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h13', speaker: 'mensah', duration: 2.167, text: 'Granite here. Solid launch, flyer.', mouth: '22<<<==22200000<<<<<<<====<<<<222', open: '047875443211016889788743258986421', vis: '-----ee-----------ooooeeee-------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h14', speaker: 'admiral', duration: 3.928, text: 'Recovery has your pod. Your reserve is ready. Fly.', mouth: '33333444444444433333300000<<<<<<<<<<<==<<<<<00000000<<<====', open: '06868778778757854665321104899878998576588653211000058987421', vis: '-------------------------oooooo------ee----ee---------eeeee', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h15', speaker: 'nomad', duration: 3.606, text: 'Every great pilot loses a ship. Great ones get back up.', mouth: '==<<<<<<<<33<<<<<<<<<<<<<==220000000055<<<<<<<<<<<<<<00', open: '0688898898568997899888878753211000068778988768858874321', vis: 'ee-------------ooooo--eeeee----------ooooo----ee-------', emotion: 'warm'),
    ],
  ),
  'groundMissileLaunch': CommsTriggerSpec(
    name: 'groundMissileLaunch',
    priority: 6,
