    group: 'ground',
    lines: [
      CommsLine(id: 'groundMissileLaunch.h0', speaker: 'kessler', duration: 1.995, text: 'Missile up! It\'s going for you!', mouth: '5544444<<<2222===<<<3334445555', open: '037757789742532378874666776421', vis: 'oo------------ee----------oooo', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h1', speaker: 'voss', duration: 1.966, text: 'Launch from the ground! Break off!', mouth: '55555======<<4442200000<<<<222', open: '037876367678877632114878985321', vis: 'oo---eeeeeeee-----------------', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h2', speaker: 'anvil', duration: 1.987, text: 'Missile from below. Move.', mouth: '2222233223333<<<55===<<<<<5555', open: '036776534657789875324899986421', vis: '-----------oo---ooee-----ooo--', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h3', speaker: 'wisp', duration: 2.473, text: 'Ground launch detected. Sidestep it.', mouth: '555<<<<<5555555==<<<<000000<<====33222', open: '03788899765545854885321101588647556321', vis: 'ooo----ooooo--eee------------eeee-----', emotion: 'urgent'),
