    lines: [
      CommsLine(id: 'groundPressureEased.h0', speaker: 'march', duration: 1.987, text: 'We\'re pushing them back! Keep it up!', mouth: '335555==555555====00000<<<<<<<', open: '056336556776467753211068899853', vis: '--oo--eeooooooeeeee-----------', emotion: 'triumphant'),
      CommsLine(id: 'groundPressureEased.h1', speaker: 'kessler', duration: 2.149, text: 'They\'re running! Bulwark advances!', mouth: '22255<<<<<=====<<<<===<<<33444400', open: '047668888874215888856479956775321', vis: '---oo---eeee---ooooee------------', emotion: 'excited'),
      CommsLine(id: 'groundPressureEased.h2', speaker: 'voss', duration: 2.578, text: 'Line\'s holding. We\'ve got room to breathe.', mouth: '33<<<<<<44443333000000<<<<<<55555442200', open: '048988757777664321168688689876577774211', vis: '---------------------eee--ooooooo------', emotion: 'warm'),
      CommsLine(id: 'groundPressureEased.h3', speaker: 'mensah', duration: 2.141, text: 'Granite\'s moving forward again. Thanks to you.', mouth: '222<<<<<4444<<<<<2222======<<<<<<', open: '047885787747899854321265446898532', vis: '-----------ooo-------eeeee-------', emotion: 'warm'),
      CommsLine(id: 'groundPressureEased.h4', speaker: 'admiral', duration: 3.149, text: 'The ground line is holding. Well done, everyone.', mouth: '3333<<<<<<<<<55<<=====4433==0000<<<<<<<<44444422', open: '054789988999857897437877654321168989999877777642', vis: '-----------oooo--ee-------eee---------------oo--', emotion: 'warm'),
