  'transmissionMission': CommsTriggerSpec(
    name: 'transmissionMission',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.h0', speaker: 'admiral', duration: 6.053, text: 'Pilot, Overwatch. The fleet is moving on your signal. What you do next decides this war.', mouth: '===<<<<========4444333000000000000<<<<<<<<<<<<44444422000000<<<<<<<<<========<<<<<==5553322', open: '0268875532168787764553211000474787889999978888776677421110068898999986542575788647636776532', vis: 'ee-----ee--------------------------oooooo------------------------oo--eeeeeee------eeoo-----', emotion: 'calm'),
      CommsLine(id: 'transmissionMission.h1', speaker: 'lindqvist', duration: 4.692, text: 'Beacon here. Long-range scans show the brood massing ahead. Stay sharp.', mouth: '33333333322000000000<<<<<<==<<<<===555<<5555333===33==000===<<444442200', open: '06866645442110000017889998778888778776897478657767653211023688777753211', vis: '-------------------------eee--ooeeeooooooo-----ee---ee---ee------------', emotion: 'calm'),
      CommsLine(id: 'transmissionMission.h2', speaker: 'admiral', duration: 3.837, text: 'Every sector you clear brings our people home. Thank you, pilot.', mouth: '==========<<<<<444444<<<<<444<<<<<<<<<000000<<<<334444====', open: '0685775876878647777478878977788899864321100688785677775321', vis: 'eeeeeee---------------------------oo------------------ee--', emotion: 'warm'),
    ],
  ),
  'transmissionMission.1': CommsTriggerSpec(
    name: 'transmissionMission.1',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.1.h0', speaker: 'admiral', duration: 3.999, text: 'Krybor\'s frontier is waiting. The outpost families are counting on you, pilot.', mouth: '00000<<44<<<<<<<44333==000000<<<<<<<<<<<<<<<<<<<<<<334444===', open: '016878876886877677666421100177987885789998756898888656666432', vis: '---------------------ee-----------ee----------oooo-------eee', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.1.h1', speaker: 'kestrel', duration: 4.622, text: 'Krybor ridge ahead. Brood scouts everywhere. Keep your eyes moving.', mouth: '000<<<<<<<<<<<<<<4444==0000000<<<<===<<<<<<<<<<<<<<333<<<<<<<<<5555222', open: '0158998999899978877764211001368987657886468787877636678888878987766432', vis: '------oo-------------ee--------oooee------------------------ooooooo---', emotion: 'calm'),
    ],
  ),
  'transmissionMission.2': CommsTriggerSpec(
    name: 'transmissionMission.2',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.2.h0', speaker: 'admiral', duration: 4.831, text: 'Next stop, the Ringfall belt. Break their supply line and the brood starves.', mouth: '55<<====<<<<000<<<<<<<44444==0000000044<<<<<<<<<<<<<<<<<<<<<====<<<<===00', open: '0589543688532178999678777533211000168778774788888887897678986657886444211', vis: 'ooooeee--------------------ee------------------------oo--oooeee-----eee--', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.2.h1', speaker: 'lindqvist', duration: 4.124, text: 'Ringfall patrols are dense. Fly fast, don\'t linger in the rings.', mouth: '33<<<5555553333334455==00000000<<44<<<=====<<44<<444444455==00', open: '06897775433555445776433211000068976887532148967887777677764211', vis: '-----ooooo---------ooeee--------------eeee--------------ooee--', emotion: 'calm'),
    ],
  ),
  'transmissionMission.3': CommsTriggerSpec(
    name: 'transmissionMission.3',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.3.h0', speaker: 'admiral', duration: 4.705, text: 'Ember Moon. Their foundries build every demon you\'ve fought. Shut them down.', mouth: '==<<<<<<<<55===00000===<<<<<33<<<<<<4444<<<<55==444===000====5544444222', open: '05898999887653211068647988876688668877778987775377643211036746777765421', vis: 'eeee--ooooooeee-----ee------------------ooooooee---ee----eeeeoo--------', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.3.h1', speaker: 'nomad', duration: 3.693, text: 'It gets hot over the Ember forges. Trust your instruments.', mouth: '333333====55<<<<<<<<<<<<<<<<<===000000<<===<<<========00', open: '06768544687589999999874788766542111004886578997577643321', vis: '------eeoooooooo--oo---oooo--ee--------eee----eee---ee--', emotion: 'calm'),
    ],
  ),
  'transmissionMission.4': CommsTriggerSpec(
    name: 'transmissionMission.4',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.4.h0', speaker: 'admiral', duration: 3.572, text: 'The Hollow answers one command. Find it, and cut it.', mouth: '444<<<<<<<<<<55<<<44433222000000<<<<==0000<<<=======00', open: '067899988977867888677654321100068986532116885457643211', vis: '-----------oooo---------------------eee------ee--eee--', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.4.h1', speaker: 'wisp', duration: 3.936, text: 'The Hollow\'s towers are broadcasting something. I\'ll keep listening.', mouth: '3344<<<<===<<4444433<<<<44==3333322333300000000==33333333300', open: '057789986478877646658976775455465345543211005875656654554321', vis: '-------eee----------oo----ee----------ee-------ee-----------', emotion: 'calm'),
    ],
  ),
  'transmissionMission.5': CommsTriggerSpec(
    name: 'transmissionMission.5',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.5.h0', speaker: 'admiral', duration: 5.038, text: 'The Carrier. This is the heart of the brood. Everything we have is behind you.', mouth: '555==<<4444===00055<<==<<<<44<<<<<<<<<<<<===0000000<<<<<<44<<4444<<<<<444422', open: '0485588777653211036897588896798657686898753211006878888987798777788888777742', vis: 'oooee------ee----oo--eeee-----ee---oo----eee--------------------------------', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.5.h1', speaker: 'lindqvist', duration: 4.661, text: 'All fleet guns are at your disposal. Break the field, then the hatch.', mouth: '000000<<554444<<44444555===<<<<<22000000000<<<<<4444422000<<<4444=====', open: '0000068974774688767857776478976532110000005886747776642116898776356432', vis: '-----ooooo-----------oooeeeooo-----------------------------------eeeee', emotion: 'calm'),
    ],
  ),
  'transmissionJunior': CommsTriggerSpec(
    name: 'transmissionJunior',
    priority: 3,
    cooldown: 120.0,
    ttl: 6.0,
    chance: 0.35,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionJunior.h0', speaker: 'pip', duration: 3.085, text: 'Captain? I just wanted to say I\'ve learned so much from you!', mouth: '33333333334444<<<<<<<<<<44<<<===<<<<<44<<<<5555', open: '06857875327787898878985377888767888986788875321', vis: '----ee--------------ee-------eeeeoo--------oo--', signature: true, emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h1', speaker: 'pip', duration: 3.316, text: 'Do you think I\'ll get my own ship someday? A real one?', mouth: '==<<<<<<<<<<<<<<<<<<<======<<<<<<<2222555<<<<<<<<<', open: '06888866885886868889876786688889953278657888898743', vis: 'ee-------eeeee-------eeeeee---------oooo---oo-----', emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h2', speaker: 'sunny', duration: 3.832, text: 'Quick question. Can demons get sunburns? Asking for science.', mouth: '3332244======000555<<<<<<<<<<<<<<<<<22222222222==<<<<<==00', open: '0664276446632116766899986753588899864227857878755888742211', vis: '-------eeeeee---ooooooooo------------------oo--ee-----ee--', signature: true, emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h3', speaker: 'rook', duration: 3.354, text: 'Betting pool says you\'ll beat my score. I put money on you!', mouth: '=====55==33335554444=====<<<22224444<<<<<<<<4442200', open: '036645554554775377677655788642787787889999887754211', vis: 'eeeeeooee----oo-----eeeeoo--------oo---------------', emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h4', speaker: 'sparrow', duration: 3.252, text: 'When this is over, first round\'s on me. Deal?', mouth: '0000<<<444<<444==0000===<<<4444<<<<==000000<<<<<<', open: '0005899676897753211687478997777898632110037887532', vis: '---------------ee----ee------------ee------------', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h5', speaker: 'wisp', duration: 3.644, text: 'I logged your last run. Your dodge rate is ridiculous.', mouth: '33<<<44<<<<<==44555500000000000<<<<<<3333333=========00', open: '0589976889987577653211000000566897788555454763455333211', vis: '------------ee--ooo------------ooo----------eeeeeeeee--', emotion: 'calm'),
      CommsLine(id: 'transmissionJunior.h6', speaker: 'nomad', duration: 3.152, text: 'Thirty years flying, and you still surprise me.', mouth: '00000000<<<<<<===<<<33300000<<==<<55555<<<<<====', open: '000068758999986478876532110689748876647898887532', vis: '-----------oooeee-----------eeeeoooo--------ee--', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h7', speaker: 'kestrel', duration: 2.6, text: 'Between us? You fly like a natural.', mouth: '555533<<<<<==000000044<<<<<<<<<<<4442200', open: '0367568998753211027866899878888756754211', vis: 'oo---------eee--------------------------', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h8', speaker: 'pip', duration: 2.873, text: 'I named my training drone after you! Is that weird?', mouth: '==<<<<<<==<<<<<<<<<<<<<<<<555000000<<<<<<222', open: '06899898768888888986888888742116787899997421', vis: 'eeeeeeeeee---------------ooooo----ooee------', emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h9', speaker: 'anvil', duration: 3.253, text: 'Hydrate, pilot. Commander\'s orders. Well, my orders.', mouth: '22222222233220000<<<<<<<<<==0000<<<5555<<<<<<====', open: '0268666335532111589998986442110689854578988643321', vis: '----------------------oo--ee-----oooo----oo--ee--', emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h10', speaker: 'sunny', duration: 2.017, text: 'Fun fact: you\'re the brightest star in this sector.', mouth: '3333<<==000444<<<<<<<<<<<<33300', open: '0587985321677588867988768554321', vis: '------eee------------ooeee-----', signature: true, emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h11', speaker: 'rook', duration: 3.015, text: 'Admiral says I talk too much. Rook, out. Wait, one more thing.', mouth: '====55555555442233322000000==<<<<<<<<<<<<<====', open: '0356665656436743555421111786689768878887886421', vis: 'eeeeoooooooo---------------ee-------------ee--', emotion: 'teasing'),
    ],
  ),
